INSERT INTO lessons (course_id, title, description, content, sort_order)
SELECT c.id, lesson.title, lesson.description, lesson.content, lesson.sort_order
FROM courses c
CROSS JOIN (VALUES
    ('java-foundations', 'Getting started with Java', 'Set up the language and understand how a Java program runs.', 'Java is a strongly typed, object-oriented language that runs on the Java Virtual Machine. A Java application begins in a class with a main method.\n\nA useful first step is to separate a program into small, named units of work. Classes describe the data and behavior that belong together.', 1),
    ('java-foundations', 'Objects and classes', 'Model useful concepts with classes, fields, and methods.', 'A class is a blueprint; an object is one concrete instance of that blueprint. Fields hold the state of an object, while methods describe what it can do.\n\nKeep each class focused on one concept. Encapsulation protects its state and gives other code a small, clear interface.', 2),
    ('java-foundations', 'Collections and error handling', 'Work with lists and handle expected failures.', 'Collections store groups of values. ArrayList is a practical starting point when you need an ordered, resizable list. Use generics such as List<String> so the compiler can check the values you place inside.\n\nExceptions communicate that an operation could not complete. Catch an exception only when your code can recover or add useful context.', 3),
    ('python-for-everyone', 'Python basics', 'Learn values, variables, and expressions.', 'Python uses indentation to define blocks. Variables refer to values, and you do not need to declare a variable type before using it.\n\nStrings, numbers, booleans, lists, and dictionaries are common building blocks. Choose names that explain what a value represents.', 1),
    ('python-for-everyone', 'Functions and modules', 'Organize reusable behavior into functions.', 'A function gives a name to a useful operation. Parameters make the operation reusable, and a return value lets the caller use its result.\n\nModules group related functions and classes. Split code into modules when that makes responsibilities easier to understand.', 2),
    ('python-for-everyone', 'Working with data', 'Transform lists and dictionaries safely.', 'Lists preserve order and dictionaries map keys to values. Loops let you process data one item at a time; comprehensions provide a concise way to build a new collection.\n\nValidate external data before relying on it. Clear error messages make a program easier to use and debug.', 3),
    ('modern-web-development', 'How the web works', 'Connect browsers, servers, and HTTP requests.', 'A browser sends an HTTP request to a server, and the server responds with a status code and content. HTML describes page structure, CSS controls presentation, and JavaScript adds behavior.\n\nUse semantic HTML so the meaning of the page is clear to browsers, assistive technology, and other developers.', 1),
    ('modern-web-development', 'Responsive layouts', 'Build pages that adapt to screen sizes.', 'Responsive design uses flexible layouts and media queries so a page remains usable on narrow and wide screens. Start with the content and let the layout adapt to available space.\n\nUse CSS Grid for two-dimensional page structure and Flexbox for arranging items along one axis.', 2),
    ('modern-web-development', 'Accessible interactions', 'Make common controls clear and usable.', 'Use native buttons for actions and links for navigation. Every form control needs a visible label, and keyboard users should be able to reach and operate every control.\n\nGood contrast, clear focus styles, and meaningful heading order improve the experience for everyone.', 3),
    ('data-structures-algorithms', 'Arrays and linked lists', 'Compare common ways to organize sequences.', 'Arrays provide fast access by index but may require moving values when items are inserted. Linked lists connect nodes, which can make insertion easier when you already have the correct node.\n\nChoose a structure based on the operations your application performs most often.', 1),
    ('data-structures-algorithms', 'Stacks and queues', 'Model last-in-first-out and first-in-first-out work.', 'A stack removes the most recently added item first. A queue removes the oldest item first. These rules are useful for undo history, task processing, and breadth-first search.\n\nDescribe the expected operations and their costs before choosing an implementation.', 2),
    ('data-structures-algorithms', 'Searching and sorting', 'Understand the costs of common algorithms.', 'Linear search checks items one at a time. Binary search repeatedly halves a sorted range, which greatly reduces the number of comparisons.\n\nBig O notation describes how the work grows as the input gets larger. It helps compare approaches without relying on a particular computer.', 3),
    ('database-design-sql', 'Relational data modeling', 'Turn real concepts into tables and relationships.', 'A relational database stores records in tables. Primary keys identify rows, while foreign keys connect related rows and protect referential integrity.\n\nNormalize repeated facts into clear tables. A unique constraint is a useful final guard against duplicate records.', 1),
    ('database-design-sql', 'Querying with SQL', 'Retrieve and combine records with SQL.', 'SELECT retrieves columns, WHERE filters rows, and ORDER BY sets a predictable order. JOIN combines related tables through their keys.\n\nUse parameters for user-provided values. Parameterized queries keep data separate from SQL instructions.', 2),
    ('database-design-sql', 'Transactions and indexes', 'Keep updates consistent and speed up common lookups.', 'A transaction groups changes so they succeed or fail together. This protects data when a multi-step operation encounters an error.\n\nIndexes speed up reads for selected access patterns, but they also use storage and add work to writes. Add them for real query needs.', 3)
) AS lesson(slug, title, description, content, sort_order)
WHERE c.slug = lesson.slug;
